import React from "react";
import { HashRouter, Routes, Route, Link } from "react-router-dom"
import "./App.css";
import BlurHome from "./defaultresort/mainhome/blurHome";
import BlurredList from "./defaultresort/mainhome/blurredlist";
import Navigation from "./navigationpage";
// import MainHome from "./defaultresort/mainhome/mainhome";
const LazyLink = React.lazy( () => import("./linkpage/linkpage") )
const LazyMainHome = React.lazy( () => import("./defaultresort/mainhome/mainhome") )


function App() {
  return (
    <HashRouter>
      <Navigation />
      <Routes>

        <Route path="/" element={
          <React.Suspense fallback={<><BlurHome /><BlurredList /></>} >
            <LazyMainHome />
          </React.Suspense>
        } />

        <Route path="/link" element={
          <React.Suspense fallback={<><BlurHome /><BlurredList /></>} > 
            <LazyLinke />
          </React.Suspense>
        } />

      </Routes>
    </HashRouter>
  );
}

export default App;
